// Hides lower-priority fluid versions from EMI.
// Lower-priority fluids are added to the kubejs:hidden_fluids tag. EMI hides that tag.
// Generated by build_hide.py from config/almostunified/fluids.json.

var PRIORITY = ["minecraft", "kubejs", "crafttweaker", "thermal", "ae2", "create", "mekanism", "immersiveengineering", "avaritia", "tconstruct", "gtceu", "nuclearcraft"];
var FLUIDS = ["hydrogen", "oxygen", "steam", "chlorine", "ethylene", "aluminum", "ammonia", "argon", "arsenic", "beryllium", "brass", "bronze", "carbon", "carbon_dioxide", "carbon_monoxide", "chromium", "cobalt", "copper", "creosote", "deuterium", "electrum", "ender", "enderium", "ethanol", "ethene", "fluorine", "glass", "glowstone", "gold", "heavy_water", "helium", "helium_3", "honey", "hsla_steel", "hydrochloric_acid", "hydrofluoric_acid", "hydrogen_chloride", "ice", "invar", "iron", "lead", "lithium", "magnesium", "magnesium_diboride", "manganese", "mercury", "methanol", "molybdenum", "neon", "nickel", "nitric_acid", "nitric_oxide", "nitrogen", "nitrogen_dioxide", "obsidian", "oil", "osmium", "palladium", "platinum", "plutonium_241", "radon", "redstone", "rocket_fuel", "rose_gold", "silver", "sodium", "steel", "sulfur_dioxide", "sulfur_trioxide", "sulfuric_acid", "thorium", "tin", "tritium", "tungsten", "uranium", "uranium_235", "uranium_hexafluoride", "uranium_oxide", "zinc"];
var TEMPLATES = ["forge:{fluid}", "forge:molten_{fluid}", "forge:liquid_{fluid}", "forge:{fluid}_gas"];

function fluidRank(id) {
    var r = PRIORITY.indexOf(id.split(":")[0]);
    return r < 0 ? 999 : r;
}

ServerEvents.tags('fluid', function (event) {
    var hidden = 0;
    FLUIDS.forEach(function (name) {
        var ids = {};
        TEMPLATES.forEach(function (t) {
            var tag = t.split("{fluid}").join(name);
            try {
                event.get(tag).getObjectIds().forEach(function (id) { ids[String(id)] = true; });
            } catch (e) { }
        });
        var list = Object.keys(ids);
        if (list.length < 2) return;
        list.sort(function (a, b) { return fluidRank(a) - fluidRank(b); });
        for (var i = 1; i < list.length; i++) {
            event.add("kubejs:hidden_fluids", list[i]);
            event.add("c:hidden_from_recipe_viewers", list[i]);
            hidden++;
        }
    });
    console.log("LAPGCHIDE hidden fluid entries: " + hidden);
});
